<?php
// RouteCam share links with a real preview per ride / channel.
//
//   https://…/routecam/r.php?id=route-3   → ride
//   https://…/routecam/r.php?u=maurice    → channel
//
// Link previews (WhatsApp, iMessage, Facebook, X, Telegram, Slack …) are built by crawlers
// that read the HTML but never run JavaScript. The app itself is a static page, so every
// address looks the same to them. This script writes the right title + image into the HTML,
// and sends people (who do run JavaScript) straight on to the ride in the app.
//
// Data: share-index.json (built-in rides, generated by `npm run build`), and – once accounts
// exist – Supabase (fill in the two constants below and adjust the query to the real schema).

const SUPABASE_URL = '';      // e.g. https://xyz.supabase.co
const SUPABASE_ANON_KEY = ''; // public anon key (row level security decides what it may read)

header('Content-Type: text/html; charset=utf-8');
header('Cache-Control: public, max-age=300');

$base = rtrim(dirname($_SERVER['SCRIPT_NAME']), '/');            // e.g. /routecam
$host = (isset($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off' ? 'https' : 'http') . '://' . $_SERVER['HTTP_HOST'];
$appUrl = $host . $base . '/';

$rideId    = isset($_GET['id']) && preg_match('/^[A-Za-z0-9_-]{1,64}$/', $_GET['id']) ? $_GET['id'] : null;
$channelId = isset($_GET['u'])  && preg_match('/^[A-Za-z0-9_.-]{1,128}$/', $_GET['u'])  ? $_GET['u']  : null;

$index = json_decode(@file_get_contents(__DIR__ . '/share-index.json'), true) ?: ['rides' => [], 'channels' => []];

function supabase_get($path) {
  if (!SUPABASE_URL || !SUPABASE_ANON_KEY) return null;
  $ctx = stream_context_create(['http' => [
    'timeout' => 3,
    'header' => "apikey: " . SUPABASE_ANON_KEY . "\r\nAuthorization: Bearer " . SUPABASE_ANON_KEY . "\r\n",
  ]]);
  $res = @file_get_contents(rtrim(SUPABASE_URL, '/') . '/rest/v1/' . $path, false, $ctx);
  $rows = $res ? json_decode($res, true) : null;
  return is_array($rows) && count($rows) ? $rows[0] : null;
}

// Best YouTube thumbnail: maxres (1280×720) when the video has one, else hq (480×360, always there)
function thumb($videoId) {
  $max = "https://img.youtube.com/vi/$videoId/maxresdefault.jpg";
  $h = @get_headers($max, false, stream_context_create(['http' => ['method' => 'HEAD', 'timeout' => 2]]));
  if ($h && strpos($h[0], '200') !== false) return [$max, 1280, 720];
  return ["https://img.youtube.com/vi/$videoId/hqdefault.jpg", 480, 360];
}

// defaults: the app's own preview
$title = 'RouteCam';
$desc  = 'Fahrvideos auf dem 3D-Globus: Video und GPS-Strecke laufen synchron.';
$image = [$host . $base . '/og-image.jpg', 1200, 630];
$target = $appUrl;

if ($rideId) {
  $ride = null;
  foreach ($index['rides'] as $r) if ($r['id'] === $rideId) { $ride = $r; break; }
  if (!$ride) {
    // user rides (schema to be confirmed when Supabase is set up)
    $row = supabase_get('rides?id=eq.' . rawurlencode($rideId) . '&visibility=in.(public,unlisted)&select=title,video_id,distance_km,duration_seconds,owner:profiles(name)');
    if ($row) $ride = ['title' => $row['title'], 'videoId' => $row['video_id'], 'km' => round($row['distance_km'] ?? 0),
                       'minutes' => round(($row['duration_seconds'] ?? 0) / 60), 'ownerName' => $row['owner']['name'] ?? null];
  }
  if ($ride) {
    $owner = $ride['ownerName'] ?? ($index['channels'][$ride['ownerId'] ?? '']['name'] ?? null);
    $title = $ride['title'];
    $desc  = trim(($ride['km'] ? $ride['km'] . ' km · ' : '') . ($ride['minutes'] ? $ride['minutes'] . ' Min. Video' : '') . ($owner ? ' · von ' . $owner : '') . ' – auf der Karte mitfahren bei RouteCam', ' ·');
    $image = thumb($ride['videoId']);
  }
  $target = $appUrl . '?route=' . rawurlencode($rideId);
} elseif ($channelId) {
  $ch = $index['channels'][$channelId] ?? null;
  $latest = null;
  foreach ($index['rides'] as $r) if (($r['ownerId'] ?? '') === $channelId) { $latest = $r; break; }
  if (!$ch) {
    $row = supabase_get('profiles?id=eq.' . rawurlencode($channelId) . '&select=name');
    if ($row) $ch = ['name' => $row['name']];
  }
  if ($ch) {
    $title = $ch['name'] . ' auf RouteCam';
    $desc  = isset($ch['rides']) ? $ch['rides'] . ' Fahrten · ' . number_format($ch['km'] ?? 0, 0, ',', '.') . ' km' : 'Fahrten auf dem 3D-Globus';
    if ($latest) $image = thumb($latest['videoId']);
  }
  $target = $appUrl . 'channel?u=' . rawurlencode($channelId);
}

$e = fn($s) => htmlspecialchars((string)$s, ENT_QUOTES, 'UTF-8');
$self = $host . $_SERVER['REQUEST_URI'];
?><!doctype html>
<html lang="de">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title><?= $e($title) ?> – RouteCam</title>
<meta name="description" content="<?= $e($desc) ?>">
<meta property="og:type" content="video.other">
<meta property="og:site_name" content="RouteCam">
<meta property="og:title" content="<?= $e($title) ?>">
<meta property="og:description" content="<?= $e($desc) ?>">
<meta property="og:url" content="<?= $e($self) ?>">
<meta property="og:image" content="<?= $e($image[0]) ?>">
<meta property="og:image:width" content="<?= $image[1] ?>">
<meta property="og:image:height" content="<?= $image[2] ?>">
<meta name="twitter:card" content="summary_large_image">
<meta name="twitter:title" content="<?= $e($title) ?>">
<meta name="twitter:description" content="<?= $e($desc) ?>">
<meta name="twitter:image" content="<?= $e($image[0]) ?>">
<link rel="canonical" href="<?= $e($self) ?>">
<style>body{margin:0;background:#0b0d10;color:#fff;font:15px system-ui,sans-serif;display:grid;place-items:center;min-height:100vh}a{color:#CCFF00}</style>
</head>
<body>
<p>Weiter zu <a href="<?= $e($target) ?>"><?= $e($title) ?></a> …</p>
<script>location.replace(<?= json_encode($target, JSON_UNESCAPED_SLASHES) ?>);</script>
</body>
</html>
